        module.launch(
            "convtrans3d_fwd",
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, block_y, block_z),
            arguments=[
                x.contiguous(),
                w.contiguous(),
                bias_arg,
                out,
                i32(B),
                i32(IC),
                i32(OC),
                i32(D),
                i32(H),
                i32(W),
                i32(OD),
